js-easy-01.syntax:
// General form
typeof operand
typeof (operand)   // parentheses optional

// Always returns a string naming the operand's type
typeof 42;            // "number"
typeof "hi";          // "string"
typeof true;          // "boolean"
typeof Symbol();      // "symbol"
typeof 10n;           // "bigint"
typeof undefined;     // "undefined"
typeof function(){};  // "function"
typeof {a: 1};        // "object"
typeof [1, 2];        // "object" (arrays are objects)

// Gotchas
// - The result is a string, so compare with quotes:
//     typeof x === "string"
// - Undeclared identifiers do not throw:
//     typeof notDeclaredAnywhere;  // "undefined"
// - Variables in the temporal dead zone (let/const before
//   declaration) DO throw a ReferenceError.
// - typeof is a historical, limited check. The possible results
//   are: undefined, object, boolean, number, bigint, string,
//   symbol, function.
// - Some values are not distinguished by typeof alone; to tell
//   them apart use other checks such as Array.isArray(),
//   x === someValue, or Object.prototype.toString.call(x).
// - Language quirks from early JavaScript versions remain for
//   backward compatibility: check the MDN page for the
//   primitive values whose result may surprise you.
// - typeof never returns "null" or "array".

js-easy-03.syntax:
// General form:
//   typeof expression   -> returns a string naming the type
//   typeof(expression)  // parentheses just group; typeof is an operator, not a function

// Examples:
typeof 42;            // "number"
typeof "hi";          // "string"
typeof true;          // "boolean"
typeof Symbol();      // "symbol"
typeof 10n;           // "bigint"
typeof [1, 2];        // arrays are objects too
typeof class A {};    // classes are a special kind of function-like value

// Possible result strings (always one of these):
//   "undefined" "boolean" "number" "bigint" "string"
//   "symbol" "object" "function"
// Gotchas:
// - typeof null is a historical quirk, not what you might expect
// - typeof on an undeclared variable does not throw a ReferenceError
// - typeof returns a string, so compare with quotes: typeof x === "string"
// - Use Array.isArray() to tell arrays from plain objects
// - Result names describe categories, there is no "array" or "null" result
// - Any value with an internal [[Call]] method gets its own special result

js-easy-04.syntax:
// General form:
//   typeof operand      (returns a string)
//   typeof (operand)

// Possible result strings:
//   "undefined", "boolean", "number", "bigint",
//   "string", "symbol", "function", "object"

typeof 42;            // "number"
typeof "hi";          // "string"
typeof Symbol();      // "symbol"
typeof function () {};// "function"
typeof { a: 1 };      // plain object

// Gotchas:
// - typeof reports the language's primitive type or
//   "function"; it does not report specific built-in
//   kinds like Map, Date, or RegExp.
// - typeof null is a historical quirk.
// - Classes are functions, so typeof class {} is "function".
// - An undeclared variable does not throw:
//     typeof notDeclaredAnywhere; // "undefined"
// - Variables in the temporal dead zone (let/const
//   before declaration) DO throw a ReferenceError.
// - To tell kinds of objects apart, use other tools:
//     Array.isArray(value)
//     value instanceof Date
//     Object.prototype.toString.call(value)
// - The result is always a string, so compare with
//   quotes: typeof x === "number"

js-easy-05.syntax:
// General form
//   typeof operand      -> returns a string naming the operand's type
//   typeof(operand)     -> same thing; parentheses just group

// Examples
typeof "hello"        // a string value
typeof true           // a boolean value
typeof 10n            // BigInt literal
typeof Symbol()       // symbol
typeof function(){}   // functions get their own result
typeof undeclaredVar  // no ReferenceError for undeclared names

// Possible results (always lowercase strings):
//   "undefined" "boolean" "number" "bigint"
//   "string" "symbol" "function" "object"

// Gotchas
// - typeof reports the type category of the VALUE, not a special
//   name for each special value. Think about what kind of primitive
//   each special numeric value belongs to (Infinity, -0, etc.).
// - null is a historical quirk: it reports the same as objects.
// - Arrays, dates, regexes and plain objects all report the same
//   string; use Array.isArray() or instanceof to tell them apart.
// - Classes are functions, so they report "function".
// - typeof always returns a string, so typeof typeof x is "string".
// - Using typeof on a let/const variable in its temporal dead zone
//   throws a ReferenceError.

js-easy-06.syntax:
// General form
//   typeof operand
//   typeof (operand)
// Returns a string naming the type of the operand's value.

let count = 5;
typeof count;          // "number"
typeof "hi";           // "string"
typeof {};             // "object"
typeof function () {}; // "function"
typeof Symbol();       // "symbol"
typeof 10n;            // "bigint"

// Possible result strings:
//   "undefined", "boolean", "number", "bigint", "string",
//   "symbol", "function", "object"

// Gotchas
// - typeof is an operator, not a function; parentheses are optional.
// - The result is always a string, so compare with quotes:
//     typeof x === "number"
// - Arrays, null, and plain objects all report the same string
//   for some of these; use Array.isArray() or === null to tell apart.
// - Reading an unresolvable name normally fails with a lookup error,
//   so think about whether typeof treats a bare identifier
//   reference specially compared with other operators.
// - Variables in the temporal dead zone (let/const/class before
//   their declaration runs) are different from never-declared names:
//     typeof later; let later = 1;  // check how TDZ behaves
// - Common use: feature detection, e.g. typeof window !== "undefined"

js-easy-08.syntax:
// General form
//   a === b   strict equality: no type conversion
//   a == b    loose equality: may convert types first
//   a !== b / a != b   negated forms

// Strict equality rules:
//   - different types -> result is false
//   - same type -> compare values
//   - NaN is never equal to anything, even itself
//   - objects/arrays compare by reference, not contents

// Examples (different values from any quiz)
console.log(7 === 7);          // same type, same value
console.log(true === "true");  // boolean vs string
console.log([] === []);        // two distinct objects
const o = {}; console.log(o === o); // same reference

// Loose equality converts operands before comparing
console.log(0 == "");          // string converted to number
console.log(null == undefined); // special-case pair
console.log(null === undefined);

// Gotchas
// - NaN === NaN is false; use Number.isNaN(x) or Object.is(x, x)
// - +0 === -0 is true; Object.is(+0, -0) is false
// - Neither operator throws for mismatched primitive types
// - Prefer === unless you deliberately want coercion

js-easy-11.syntax:
// General form
//   a == b   // loose equality: if types differ, coerce, then compare
//   a === b  // strict equality: no coercion, types must match

// Simplified coercion rules for ==
//  - Same type: compared like ===
//  - null == undefined is true; neither equals anything else
//  - Number vs string: the string is converted to a number
//  - Boolean vs anything: the boolean is converted to a number first
//    (true -> 1, false -> 0), then comparison continues
//  - Object vs primitive: the object is converted to a primitive

// Examples (different values from the quiz)
console.log("5" == 5);      // string -> number, then compared
console.log(false == "");   // false -> 0, "" -> 0, then compared
console.log(null == 0);     // null only loosely equals undefined

// Gotchas
//  - NaN is never equal to anything, even itself
//  - Object.is() and === treat types strictly
//  - Prefer === to avoid surprising conversions
//  - Number(x) and Boolean(x) show how a value converts

js-easy-14.syntax:
// General form: a == b
// If types differ, the Abstract Equality algorithm coerces operands.
//
// Simplified rules when types differ:
//  1. null == undefined is true; neither equals anything else
//  2. Boolean operand -> converted to Number (true->1, false->0)
//  3. String vs Number -> string converted to Number
//  4. Object vs primitive -> object converted via ToPrimitive
//     (valueOf(), then toString()), then comparison restarts
//  5. Two objects -> compared by reference, no coercion
//
// Examples (different values from any quiz):
// '5' == 5          // string -> number, then 5 == 5
// '' == 0           // '' becomes 0
// [7] == 7          // [7] -> '7' -> 7
// ({}) == ({})      // two distinct objects: reference comparison
// null == 0         // no coercion to number for null
//
// Gotchas:
// - Step-by-step: apply rules repeatedly until both sides share a type
// - Array toString joins elements with commas: [1,2].toString() is '1,2'
// - Truthiness (if (x)) is NOT the same as == true/false
// - NaN is never equal to anything, including itself
// - Prefer === to avoid coercion; Object.is for NaN/-0 distinctions

js-easy-15.syntax:
// General form
//   a === b   -> strict equality: no type coercion
//   Different types -> false
//   Same type -> compare values (objects/arrays by reference)

console.log(5 === "5");        // false (number vs string)
console.log("hi" === "hi");    // true
console.log({} === {});        // false (different references)

const o = {};
console.log(o === o);          // true (same reference)

// Special numeric values
//   NaN is the result of invalid math, e.g. 0 / 0 or Number("abc")
//   Check the spec rule for strict equality with NaN before assuming
//   a value equals itself.
//   +0 === -0 is true, but Object.is(+0, -0) is false

// Reliable ways to test for NaN
//   Number.isNaN(x)   -> true only if x is the number NaN
//   Object.is(x, y)   -> SameValue comparison
//   isNaN(x)          -> coerces first, so isNaN("abc") is true (avoid)
//   [x].includes(NaN) -> uses SameValueZero
//   [x].indexOf(NaN)  -> uses ===

// Gotchas
//   null === undefined is false, but null == undefined is true
//   === never throws a TypeError for ordinary values

js-easy-17.syntax:
// General form
// Object.is(a, b) -> boolean
// Compares using the SameValue algorithm: no type coercion.

// Example 1: compared with ===
console.log(Object.is(7, 7));        // same number
console.log(Object.is('a', 'b'));    // different strings

// Example 2: values where it differs from ===
// Object.is(0, -0)  vs  0 === -0
// Object.is(Infinity, Infinity)

// Gotchas
// - No coercion: Object.is('1', 1) is false (unlike ==).
// - Objects compare by reference: Object.is({}, {}) is false.
// - Two special numeric cases make Object.is differ from ===:
//   signed zeros, and how the not-a-number value is treated.
// - Check how === and Number.isNaN() treat the not-a-number value
//   and compare it to what SameValue does.
// - Array.prototype.includes uses SameValueZero, which
//   treats +0 and -0 as equal but is otherwise like SameValue.
// - Never throws for any pair of arguments.

js-easy-20.syntax:
// General form
// Number(value) -> converts value to a number primitive using the ToNumber rules
//
// For strings: leading/trailing whitespace is trimmed, then the rest
// must be a valid numeric literal, otherwise the result is NaN.

Number("42");        // 42
Number("  7.5  ");   // 7.5 (whitespace trimmed)
Number("12px");      // NaN (trailing junk is not allowed)
Number("0x1F");      // 31 (hex, also 0b and 0o prefixes)
Number("1e3");       // 1000

// Gotchas
// - A string that is only whitespace is treated like an empty-ish
//   string: think about what the trimmed text represents numerically.
// - Other inputs: Number(true) -> 1, Number(false) -> 0,
//   Number(null) -> 0, Number(undefined) -> NaN
// - Number([]) and Number([5]) go through string conversion first
// - Number("1,000") -> NaN (no separators)
// - parseInt/parseFloat are more lenient: parseInt("12px") -> 12
// - Unary + behaves like Number(): +"3" -> 3
// - Check results with Number.isNaN(x), not x === NaN

js-easy-21.syntax:
// General form
// Number(value) -> a number primitive (not a Number object without `new`)

// Examples
Number("42");      // 42
Number("  7.5  ");  // 7.5  (surrounding whitespace is trimmed)
Number("");        // empty or whitespace-only string converts to a specific number
Number(true);      // 1
Number(null);      // 0
Number(undefined); // NaN

// Rules (StringToNumber)
// - The WHOLE trimmed string must be a valid numeric literal,
//   otherwise the result is NaN.
// - Accepted: decimals, exponents ("1e3"), "Infinity",
//   prefixes "0x", "0o", "0b" (no sign allowed with these).
// - Numeric separators ("1_000") are NOT accepted.
//
// Gotchas
// - Number() is strict; parseInt()/parseFloat() read a leading
//   numeric prefix and ignore trailing characters.
//     parseInt("3abc")   // reads the leading digits
//     Number("3abc")     // strict: whole string must be numeric
// - NaN !== NaN; test with Number.isNaN(x).
// - Unary plus (+str) behaves like Number(str).
// - Number(1n) works (BigInt -> number), but +1n throws TypeError.

js-easy-22.syntax:
// General form
// parseInt(string, radix)
//   string: converted to a string, leading whitespace skipped
//   radix:  integer 2-36 (use it explicitly; 10 for decimal)

// Examples (different inputs from any quiz)
parseInt("42", 10);        // 42
parseInt("  7 apples", 10); // parses leading digits only, stops at first invalid char
parseInt("ff", 16);        // 255
parseInt("101", 2);        // 5

// Rules and gotchas
// - Parsing reads from the start and stops at the first character
//   that is not a valid digit for the radix; the rest is ignored.
// - If the first non-space character cannot be a digit, the result is NaN.
// - Optional leading + or - sign is accepted.
// - Result is always a Number (or NaN), never a string.
// - Decimal points are not read: the fractional part is dropped.
// - Omitted radix: "0x" prefix means 16, otherwise 10. Pass it anyway.
// - Invalid input does not throw; it yields NaN.
// - Compare with Number(str), which is strict and returns NaN
//   if any trailing junk is present.
// - Check failures with Number.isNaN(result).

js-easy-23.syntax:
// General form
// parseInt(string, radix?)
//   string: converted to a string, leading whitespace skipped
//   radix:  integer 2-36 (omitted/0 => 10, except "0x" prefix => 16)
//   returns an integer Number, or NaN if no leading digit is valid

parseInt("42", 10);      // 42
parseInt("  17px", 10);  // 17  (stops at first invalid character)
parseInt("ff", 16);      // 255
parseInt("101", 2);      // 5
parseInt("abc", 10);     // NaN
parseInt("3.9", 10);     // 3   (fraction is truncated, not rounded)
parseInt("-12", 10);     // -12 (leading sign allowed)

// Gotchas
// - Only the leading portion is parsed; trailing junk is ignored.
// - Leading zeros are just digits when the radix is explicit.
// - Always pass the radix to avoid ambiguity (e.g. "0x1A" is read as hex when radix is omitted).
// - A radix outside 2-36 gives NaN.
// - Number("17px") is NaN, unlike parseInt: Number is strict, parseInt is lenient.
// - Never use parseInt as a map callback without a wrapper: ["1","2","3"].map(parseInt) passes the index as radix.
// - Very large or tiny numbers in exponent form are misparsed: parseInt(1e21) reads "1e+21" => 1.

js-easy-24.syntax:
// General form
// parseFloat(string)  -> number
//   1. Converts argument to a string, trims leading whitespace
//   2. Reads the longest prefix that is a valid decimal literal
//   3. Ignores the rest; returns NaN if no valid prefix exists

parseFloat("2.5");        // 2.5
parseFloat("  7.25em");   // 7.25 (leading whitespace ok, trailing text ignored)
parseFloat("-.5x");       // -0.5
parseFloat("1e3px");      // 1000 (exponent notation is understood)

// Gotchas
// parseFloat("abc9")     -> NaN (prefix must start the string)
// parseFloat("")         -> NaN
// parseFloat("1.2.3")    -> stops at the second dot
// parseFloat("Infinity") -> Infinity
// parseFloat("0x1F")     -> 0 (no hex support; stops at x)
// Always returns a number type, never a string.
//
// Compare with stricter conversion:
// Number("7.25em")       -> NaN (whole string must be numeric)
// parseInt("7.25em")     -> parses integers only, stops at the dot
// Check failures with Number.isNaN(result)

js-easy-26.syntax:
// General form:
//   +operand   -> converts operand to a Number via ToNumber
//
// Primitives:
//   +"42"     // string parsed as numeric literal
//   +true     // booleans map to 1 or 0
//   +null     // null maps to 0
//   +undefined// undefined maps to NaN
//   +"abc"    // unparseable string gives NaN
//
// Objects are first converted to a primitive (ToPrimitive, hint "number"):
//   1. call valueOf(); if it returns a primitive, use it
//   2. otherwise call toString(); use that primitive
//   3. then apply ToNumber to the resulting primitive
//
// Example with custom conversion:
const temp = { valueOf() { return "7"; } };
+temp;            // valueOf gives "7", then ToNumber parses it

const box = { toString() { return "  12  "; } };
// default valueOf returns the object itself (not primitive),
// so toString is used; whitespace is trimmed when parsing

// Gotchas:
// - Symbol.toPrimitive, if defined, takes priority over valueOf/toString
// - Unary + throws TypeError on BigInt and Symbol
// - Arrays convert via their toString (join), e.g. +[5] vs +[1,2]
// - Empty or whitespace-only strings convert to 0
// - Number(x) behaves like +x but supports BigInt

js-easy-28.syntax:
// General form
// String(value)  -> returns a primitive string (no `new`)
// Converts any value using the ToString rules.

String(123);        // "123"
String(true);       // "true"
String([1, 2]);     // "1,2"  (array join)
String({});         // "[object Object]"

// Common conversions
// numbers  -> decimal text (e.g. String(1e21) is "1e+21")
// booleans -> "true" / "false"
// objects  -> calls toString() (or valueOf via ToPrimitive hint "string")

// Symbols: String() is special-cased and works
String(Symbol("id")); // "Symbol(id)"
// but implicit conversion throws:
// "" + Symbol("id")  -> TypeError

// Compare with other approaches
// value.toString()  -> throws TypeError if value is a nullish value
// `${value}`        -> template literal, uses ToString
// value + ""        -> uses ToPrimitive (default hint), differs for some objects

// Gotchas
// new String("a") creates a wrapper object, typeof is "object"
// String(x) never needs a null/undefined check before calling
// Primitive results: typeof String(5) === "string"

js-easy-30.syntax:
// General form
// Boolean(value) -> converts value to a primitive boolean
// Uses the ToBoolean rule: only a fixed list of values is falsy;
// everything else is truthy.

// Falsy values (complete list):
//   false, 0, -0, 0n, NaN, "" (empty string), null, undefined,
//   and document.all (browser quirk)

// Examples
Boolean(0);          // a falsy number
Boolean("");         // empty string is falsy
Boolean("hello");    // non-empty string
Boolean([]);         // objects are always truthy

// Gotchas
// - Strings are judged by length only, not by what they say.
//   Any string with at least one character (even " " or "0")
//   is truthy.
// - Empty arrays [] and empty objects {} are truthy.
// - !!value is equivalent to Boolean(value).
// - new Boolean(false) creates an object, which is truthy.
// - Boolean() never throws for ordinary values and never
//   parses string contents (unlike JSON.parse).

js-easy-31.syntax:
// General form
// Boolean(value)  -> converts value to a primitive true/false
// !!value         -> same conversion via double negation
// if (value) {...} uses the same ToBoolean rule

// The falsy values (the complete list):
//   false, 0, -0, 0n, "" (empty string), null, undefined, NaN
// Also document.all (legacy browser quirk)
// Everything else is truthy, including objects.

// Examples
Boolean("hello");   // string with characters
Boolean(null);      // a falsy value
Boolean({});        // check: is an object in the falsy list?

// Gotchas
// - The rule checks the type/value, not whether a thing looks "empty".
// - Strings: "0" and "false" are non-empty strings; only "" is falsy.
// - Wrapper objects are objects: new Boolean(false) is an object.
// - Boolean(x) returns a primitive; new Boolean(x) returns an object.
// - Loose equality is a different algorithm from ToBoolean:
//   a value can be truthy in if() yet not == true.

js-easy-32.syntax:
// General form
// Boolean(value) -> converts any value to a primitive true or false
// Same rule as !!value, and as conditions in if / while / ternary

// Examples
Boolean("hello");   // a non-empty string is truthy
Boolean("");        // empty string is falsy
Boolean(null);      // null is falsy

// The complete list of falsy values:
//   false, 0, -0, 0n (BigInt zero), "" (empty string),
//   null, undefined, NaN
// document.all is also falsy (legacy quirk)

// Everything else is truthy, including surprising cases:
Boolean([]);        // empty array -> truthy
Boolean({});        // empty object -> truthy
Boolean("0");       // non-empty string -> truthy
Boolean("false");   // non-empty string -> truthy
Boolean(-5);        // any non-zero number -> truthy

// Gotchas
// - Boolean(x) returns a primitive; new Boolean(x) returns an object,
//   and objects are always truthy (even new Boolean(false)).
// - Conversion does not change the value; it only decides the result.
// - Boolean() with no argument returns false.

js-easy-33.syntax:
// General form
Boolean(value)   // returns a primitive true or false
!!value          // same conversion via double negation

// The falsy values (the complete list):
//   false, 0, -0, 0n, "" (empty string), null, undefined, NaN
// Everything else is truthy.

// Examples
Boolean("hello");   // string with content
Boolean(0);         // a falsy number
Boolean(null);      // a falsy value
Boolean("0");       // non-empty string

// Gotchas
// - Boolean() never returns NaN or undefined; the result is always a boolean.
// - Truthiness checks only whether the value is in the falsy list above.
//   Contents are not inspected, so containers are not tested for emptiness.
// - Objects are always truthy, including arrays, functions, and Date objects.
// - Don't use `new Boolean(x)`: it creates a wrapper object, which is
//   always truthy, even for new Boolean(false).
// - if, while, &&, ||, ?? and ternary conditions use the same conversion
//   (?? only checks null/undefined).

js-easy-35.syntax:
// General form:
//   left ?? right
// Evaluates to `right` only when `left` is null or undefined.
// Otherwise it evaluates to `left` (short-circuits: right is not evaluated).

const name = undefined ?? "guest";   // "guest"
const count = null ?? 10;            // 10

// Compare with ||:
//   a || b  -> b when a is ANY falsy value (0, "", false, NaN, null, undefined, 0n)
//   a ?? b  -> b only when a is null or undefined
// So ?? keeps "real" values that happen to be falsy:
const qty = "" ?? "none";           // ""  (empty string is kept)
const flag = NaN ?? 5;               // NaN

// Chaining: a ?? b ?? c  picks the first non-nullish value
// Mixing with || or && without parentheses is a SyntaxError:
//   a || b ?? c      // SyntaxError
//   (a || b) ?? c    // OK

// Works well with optional chaining:
//   obj?.size ?? 0

// Assignment form:
//   x ??= value   // assigns only if x is null or undefined

js-easy-36.syntax:
// General form:
//   left ?? right
// Evaluates to `right` only when `left` is null or undefined.
// Otherwise it evaluates to `left` (and `right` is not evaluated: short-circuit).

const a = null ?? "fallback";   // a is "fallback"
const count = 0;
const b = count ?? 10;          // decided by whether count is null/undefined

// Compare with ||:
//   || falls back on ANY falsy left value:
//     false, 0, -0, 0n, NaN, "", null, undefined
//   ?? falls back on ONLY the two nullish values:
//     null, undefined

// Gotchas:
// - Mixing with || or && without parentheses is a SyntaxError:
//     a || b ?? c        // error
//     (a || b) ?? c      // OK
// - Pairs well with optional chaining:
//     user?.name ?? "anonymous"
// - Assignment form: x ??= value  (assigns only if x is null/undefined)
// - Chains left to right: a ?? b ?? c returns the first non-nullish value
//   (or the last operand if all earlier ones are nullish).

js-easy-38.syntax:
// General form
//   obj?.prop        obj?.[expr]        fn?.(args)
// The left side is checked: if it is nullish (null or undefined),
// the rest of the chain is skipped (short-circuit) instead of
// evaluating the property access.

const user = { profile: { name: "Ana" }, greet() { return "hi"; } };
user?.profile?.name;      // "Ana" (value present, normal access)
user.settings?.theme;     // settings is missing, so the chain stops there
user.greet?.();           // calls the method only if it exists
user.items?.[0];          // optional bracket access

// Gotchas
// - Only null and undefined trigger the short-circuit; 0, "", false, NaN do not.
// - Short-circuiting skips the whole remaining chain: a?.b.c.d
//   does not evaluate .c or .d when a is nullish.
// - It guards only the value to its left. If a?.b is non-nullish
//   but b's value lacks a property, later access can still fail.
// - Cannot be used on the left of assignment: a?.b = 1 is a SyntaxError.
// - Combine with ?? for defaults: a?.b ?? "fallback".
// - Compare with plain access, which throws on a nullish base:
//   let n = undefined; n.x  // TypeError
// - Undeclared variables still throw ReferenceError.

js-easy-39.syntax:
// General form
//   callee?.(args)
// The part after ?. is evaluated only if callee is not
// null/undefined; otherwise the whole chain short-circuits.

const handler = {
  greet(name) { return 'Hi ' + name; }
};

handler.greet?.('Ana');      // method exists -> called normally
handler.missing?.('Ana');    // method absent -> see short-circuit rule

// Variations
//   obj.method?.(x)    optional method call
//   obj?.method(x)     guards obj only, not method
//   arr?.[0]           optional index access
//   a?.b.c.d()         one ?. short-circuits the rest of the chain

// Gotchas
// - Short-circuits only on null or undefined (nullish),
//   not on 0, '', false, or NaN.
// - If the value is non-nullish but not callable (e.g. a number or
//   string), calling it with ?.() still throws a TypeError.
// - Arguments are not evaluated when the chain short-circuits.
// - A short-circuited chain yields a single result value for the
//   whole expression, so check which value that is.
// - Cannot be used for assignment: a?.b = 1 is a SyntaxError.

js-easy-45.syntax:
// General form
//   let name = initializer;
//   const name = initializer;
//
// The scope of let/const is the enclosing block { }.
// The binding exists from the start of that block,
// but it is not initialized until execution reaches the declaration.
// The span between block start and declaration is the
// "temporal dead zone" (TDZ).

// Example 1: using a binding inside its TDZ
{
  // TDZ for `count` begins here
  // ...any access to `count` here is in the TDZ
  let count = 5;   // TDZ ends once this line runs
  console.log(count);
}

// Example 2: TDZ applies even inside functions
function demo() {
  const run = () => label;   // fine to define; only runs later
  const label = "ok";
  return run();              // called after initialization
}

// Gotchas
// - The TDZ is based on execution time, not on text position.
// - typeof is NOT safe for a variable in its TDZ.
// - Shadowing: an inner let hides an outer variable for the
//   WHOLE inner block, including lines before the declaration.
// - Default parameters can hit the TDZ: function f(a = b, b) {}
// - Contrast with var: hoisted and initialized to undefined.
// - Redeclaring a let name in the same scope is an early error.

js-easy-46.syntax:
// General form
//   var name = expression;
//   The declaration (the name) is processed before any code runs.
//   The assignment stays where it is written.

// Mental model: the engine treats
function demo() {
  console.log(typeof count);
  var count = 10;
  console.log(count);
}
// roughly as if written:
function demoEquivalent() {
  var count;        // declaration moved to top of its function scope
  // ...code that runs before the assignment sees count in its initial state
  count = 10;       // assignment happens in place
}

// Gotchas
// - var is scoped to the function (or global), not to blocks like { }.
// - var bindings are initialized automatically at scope entry.
// - let and const are also hoisted, but they sit in the
//   "temporal dead zone" until their declaration line runs.
//   Accessing them early follows different rules than var.
// - Function declarations are hoisted with their body;
//   function expressions assigned to var are not.
// - Redeclaring a var in the same scope is allowed.
//   var a = 1; var a = 2;
// - Undeclared names (never declared anywhere) are a different case
//   from names declared later with var.

js-easy-49.syntax:
// General form:
//   `text ${expression} more text`
// The expression inside ${...} is evaluated, converted to a string,
// and spliced into the surrounding text.

const who = "Sam";
const k = 3;
const s1 = `Hi ${who}, you have ${k + 1} items`;

// Any expression is allowed inside ${...}, including function calls,
// ternaries, and other template literals:
const tag = (x) => `<${x}>`;
const s2 = `${tag(who)} is ${k > 2 ? "big" : "small"}`;

// Gotchas:
// - ${...} is a full JavaScript expression context, so the parser
//   treats backticks inside it as the start of a new literal,
//   not as text.
// - Outside of ${...}, a backtick must be escaped as \` and a
//   literal "${" as \${ to be kept as plain text.
// - Values are converted with ToString: null -> "null",
//   undefined -> "undefined", objects -> their toString().
// - Newlines in the source are kept in the resulting string.
// - Tagged form: fn`text ${v}` calls fn with the string parts
//   and the values instead of building a string directly.

js-easy-51.syntax:
// General form:
// const result = array.map((element, index, array) => newValue, thisArg?)
//
// The callback runs once per element (skipping holes in sparse arrays).
// Whatever the callback returns becomes the value at that position.

const names = ['ann', 'bo', 'cy'];
const lengths = names.map((s) => s.length);
// lengths holds the callback results, one per element

const labeled = names.map((s, i) => `${i}:${s}`);

// Notes and gotchas:
// - Think of the return value as a separate array of the same length.
// - The callback can still change objects it receives (reference types)
//   or write to the outer array, but map itself does not do this for you.
// - A callback with no return gives undefined for every slot.
// - Use forEach when you only want side effects and no result array.
// - Common surprise: ['1','2','3'].map(parseInt) passes index as radix.
// - Chaining works because map returns an array: a.map(f).filter(g)
// - Compare: Array.from(iterable, fn) maps any iterable;
//   iterator helpers (.values().map(fn)) are the lazy variant.

js-easy-53.syntax:
// General form
// array.find(callback(element, index, array), thisArg?)
// Calls callback on each element in order until it returns a truthy value.
// Returns what the method is documented to yield for a hit, or its
// documented "not found" value if the callback never returns truthy.

const words = ['pear', 'fig', 'banana'];

const long = words.find((w) => w.length > 5);   // search by predicate
const idx  = words.findIndex((w) => w.length > 5); // sibling: index-based

// Related methods
// findLast / findLastIndex -> same idea, but search from the end
// filter(fn)   -> new array of ALL elements passing the test
// indexOf(x)   -> position by strict equality (no callback)
// includes(x)  -> boolean by SameValueZero
// some(fn)     -> boolean: does any element pass?

// Gotchas
// - Stops at the first truthy callback result; later items are not visited.
// - Callback return value only needs to be truthy, not strictly true.
// - Compare the "not found" results of find vs findIndex carefully:
//   they are different kinds of value.
// - Holes in sparse arrays are visited as undefined.
// - An element that is itself undefined is indistinguishable from
//   "not found" when using find; use findIndex if that matters.

js-easy-55.syntax:
// General form
// array.includes(searchElement)
// array.includes(searchElement, fromIndex)

// Examples
const nums = [10, 20, 30];
nums.includes(20);      // checks whether a value is present
nums.includes(10, 1);   // search starts at index 1

// Things to remember
// - The return value is a single primitive type, not a position or the element itself.
//   Compare with indexOf, which reports an index, and find, which returns an element.
// - Comparison uses SameValueZero: like ===, except NaN matches NaN.
//   [NaN].includes(NaN);  // differs from [NaN].indexOf(NaN)
// - Strings are compared by value; objects are compared by reference.
//   [{a: 1}].includes({a: 1});  // different object identity
// - Negative fromIndex counts from the end of the array.
// - Works on sparse arrays: holes are treated as undefined.
// - Types are not coerced: [1, 2].includes("1") does not match.

js-easy-57.syntax:
// General form
// const result = array.method(...args);
// Mutator methods change the array in place AND hand back a value
// that is not always the array itself. Check each method's return.

// Example 1: shift removes from the front
const queue = ['a', 'b', 'c'];
const first = queue.shift();
// first is the removed element; queue is now changed

// Example 2: unshift adds to the front
const stack = ['x'];
const r = stack.unshift('y', 'z');
// check what r holds by reading the docs for unshift

// Common variations (each mutates the original array):
// pop()      -> returns the removed last element (undefined if empty)
// shift()    -> returns the removed first element (undefined if empty)
// splice()   -> returns an array of removed elements
// sort()     -> returns the same array reference, sorted
// reverse()  -> returns the same array reference, reversed
// fill()     -> returns the same array reference

// Gotchas:
// - Return values differ per method: a length, an element,
//   an array of removed items, or the array itself.
// - Non-mutating alternatives return NEW arrays:
//   concat, slice, map, filter, toSorted, toReversed, with.
// - Chaining only works on methods that return the array.
// - A method that returns a number cannot be chained like an array.

js-easy-58.syntax:
// General form
// array.method(args) -> mutates the array AND gives back a value
// The return value is often not the array itself.

const letters = ['a', 'b', 'c', 'd'];

const r1 = letters.push('e');   // adds to end
console.log(letters);           // ['a','b','c','d','e']
// r1 is a number (see docs for what it means)

const r2 = letters.shift();     // removes from the front
console.log(letters);           // ['b','c','d','e']
// r2 is not an array: check the docs for what it holds

// Common variations and gotchas:
// - pop() and shift() take no arguments and change the array's length.
// - push() and unshift() return the new length.
// - pop() and shift() return the removed element itself,
//   not wrapped in an array.
// - splice(start, count) is different: it returns an ARRAY of removed items.
// - On an empty array, pop() and shift() return the value
//   that means "nothing here".
// - Mutating methods change the original; slice(), concat(),
//   and toSpliced() do not.
// - Ignoring the return value is fine when you only want the side effect.

js-easy-60.syntax:
// General form
// array.methodName(...args)  // some methods mutate the array in place
// Every method has two outputs to keep apart:
//   1) the side effect on the array
//   2) the value the call evaluates to (its return value)

// Example: shift removes from the front
const letters = ['a', 'b', 'c'];
const first = letters.shift();
// letters is now ['b', 'c']; first holds what shift returned

// Example: push adds to the end
const nums = [10, 20];
const r = nums.push(30, 40);
// nums is now [10, 20, 30, 40]; r holds what push returned

// Gotchas
// - Mutators change the original array; they do not copy it.
// - Return values differ by method: pop/shift return the removed
//   element, push/unshift return a number, sort/reverse return the
//   same array reference.
// - Multiple arguments are inserted together, keeping their order:
//   arr.unshift(x, y) puts x, y at the start in that order.
// - To get a new array without mutating, use spread or toSpliced:
//   const copy = [z, ...arr];
// - Check the docs' "Return value" section instead of guessing.

js-easy-61.syntax:
// General form
// array.slice(start?, end?)
//   start: index to begin copying (inclusive); default 0
//   end:   index to stop before (exclusive); default array.length
//   returns: a NEW array holding a shallow copy of the selected range

const letters = ['a', 'b', 'c', 'd', 'e'];

const mid = letters.slice(1, 3);   // elements at index 1 and 2
const tail = letters.slice(-2);    // negative index counts from the end

// Variations and gotchas
// - slice() with no arguments makes a shallow copy of the whole array.
// - If start >= length, the result is an empty array [].
// - Negative values are offsets from the end: length + value.
// - end is exclusive: slice(1, 3) does not include index 3.
// - Shallow copy: nested objects/arrays are shared by reference.
// - Compare with splice(start, deleteCount, ...items), which is a
//   different method that changes the array it is called on.
// - Works on strings too (String.prototype.slice) and returns a string.
// - Return value and original array are separate objects; check each
//   one separately when reasoning about what a call produces.

js-easy-62.syntax:
// General form:
// array.splice(start, deleteCount, item1, item2, ...)
//   start       index where changes begin (negative counts from the end)
//   deleteCount how many elements to remove starting at start
//   items       optional elements to insert at start

const letters = ['a', 'b', 'c', 'd', 'e'];

// Remove two elements starting at index 2
const gone = letters.splice(2, 2);
// Check what the return value is and what happened to `letters`
// by logging both: console.log(gone, letters);

// Insert without removing (deleteCount = 0)
const nums = [10, 20, 30];
nums.splice(1, 0, 15, 17);

// Replace: remove and insert in one call
const words = ['x', 'y', 'z'];
words.splice(0, 1, 'w1', 'w2');

// Gotchas:
// - splice MUTATES the array it is called on (in place).
// - The return value is always an array of the removed elements,
//   (empty array if nothing was removed).
// - Omitting deleteCount removes everything from start to the end.
// - Negative start: splice(-1, 1) targets the last element.
// - Non-mutating alternatives: slice() to copy a range,
//   toSpliced() to get a modified copy.

js-easy-65.syntax:
// General form:
// const copy = { ...source1, ...source2, extraKey: value };
//
// Own enumerable properties of each source are copied in order,
// left to right, into the new object.
// When the same key appears more than once, the property is
// assigned each time it is encountered, so position matters.

const defaults = { color: 'red', size: 10 };
const custom = { size: 20, weight: 5 };

const x = { ...defaults, ...custom, id: 7 };
// keys: color, size, weight, id  (see order rule above to work out each value)

const y = { id: 1, ...defaults, id: 2 };
// explicit keys are also subject to the same left-to-right order

// Variations and gotchas:
// - Spread is shallow: nested objects are shared by reference.
// - null and undefined sources are ignored: { ...null } is {}.
// - Primitives: strings spread as indexed characters, numbers add nothing.
// - Only own enumerable properties are copied (no prototype props).
// - Getters are invoked and their values copied as plain data.
// - Symbol-keyed own enumerable properties are copied too.
// - Arrays spread into objects as index keys: { ...['a','b'] } -> {0:'a',1:'b'}.
// - Similar to Object.assign({}, a, b), but spread does not call setters on the target.

js-easy-66.syntax:
// General form:
// const [name = defaultExpr] = iterable;
// The default is used only when the matched value is
// strictly the value undefined (or the element is missing).

const [x = 10] = [5];        // existing value is used
const [y = 10] = [];         // missing element -> default applies

// Object destructuring follows the same rule:
const { p = 'dflt' } = { p: 'given' };

// Variations and gotchas:
// - The default is evaluated lazily, only when needed:
//   const [m = compute()] = [3];   // compute() is not called
// - Defaults can use earlier bindings:
//   const [s = 1, t = s + 1] = [];
// - Other falsy values (0, '', false, NaN) are real values,
//   so they are kept rather than replaced.
// - Compare with ?? and ||, which treat values differently:
//   value ?? fallback   // nullish check
//   value || fallback   // falsy check
// - Defaults also work in function parameters:
//   function f({ k = 2 } = {}) {}
// - Check precisely which values trigger the default:
//   only one specific value does, not every 'empty-looking' one.

js-easy-70.syntax:
// General form
// const { prop = defaultValue } = object;
// The default is used only when the extracted value is strictly undefined
// (the property is missing, or explicitly holds undefined).

// Example 1: missing property
const { color = 'red' } = { size: 10 };

// Example 2: renaming plus a default
const { size: s = 5, weight: w = 0 } = { size: undefined, weight: 7 };

// Example 3: function parameter
function draw({ x = 0, y = 0 } = {}) {
  return [x, y];
}

// Gotchas
// - Only undefined triggers the default. Other falsy values
//   (0, '', false, NaN, and null) are kept as they are.
// - This differs from `||`, which replaces any falsy value,
//   and from `??`, which replaces null as well as undefined.
// - The default expression is evaluated lazily, only when needed.
// - Defaults can refer to earlier destructured names:
//   const { p = 1, q = p + 1 } = {};
// - Destructuring null or undefined itself throws a TypeError;
//   give the whole pattern a fallback: `= {}`.

js-easy-71.syntax:
// General form
// const { prop } = object;
// const { prop: newName } = object;
// const { prop = fallback } = object;
// const { prop: newName = fallback } = object;

// Example 1: reading and renaming
const user = { name: 'Ada', age: 36 };
const { name, age: years } = user;
// name -> 'Ada', years -> 36

// Example 2: default values
const { city = 'Unknown', name: n = 'Anon' } = { name: 'Bo' };
// A default is used only when the property value is undefined

// Variations and gotchas
// - Nested: const { p: { q } } = obj;  (throws if obj.p is null/undefined)
// - Rest: const { x, ...others } = obj;  collects remaining own enumerable props
// - Destructuring null or undefined throws a TypeError
// - Defaults do NOT apply to null, 0, '' or false
// - Without const/let, wrap in parentheses: ({ x } = obj);
// - In parameters: function f({ a = 1, b } = {}) { }
// - Properties are looked up by name, not by position (unlike arrays)

js-easy-75.syntax:
// General form:
// for (const|let|var binding of iterable) { body }
// binding is assigned each item produced by the iterable's iterator

const fruits = ["apple", "pear", "plum"];
for (const f of fruits) {
  console.log(f.toUpperCase());
}

// Works on any iterable: arrays, strings, Map, Set, NodeList,
// generators, arguments, typed arrays
for (const ch of "hey") { /* one character per step */ }

// Destructuring in the binding
for (const [k, v] of new Map([[1, "x"]])) { }
for (const [i, f] of fruits.entries()) { }

// Gotchas:
// - Plain objects are NOT iterable: for (x of {a:1}) throws TypeError
//   (use Object.keys / values / entries instead)
// - Contrast: for...in loops over enumerable property keys
//   (strings), not over the iterable's items
// - const is fine: each iteration creates a new binding
// - break / return / throw close the iterator early
// - Use `for await (const x of asyncIterable)` for async iterables

js-easy-76.syntax:
// General form
for (const key in expression) {
  // key is a string property name
}

// Example: a different shape of object
const base = { color: 'red' };
const item = Object.create(base);
item.size = 9;
for (const k in item) {
  console.log(typeof k); // keys are always strings
}

// Related tools
// Object.keys(o)     -> own enumerable string keys only
// Object.entries(o)  -> own enumerable [key, value] pairs
// Object.hasOwn(o, k) -> true if k is an own property
// for (const k in o) { if (!Object.hasOwn(o, k)) continue; ... }

// Gotchas
// - Walks the prototype chain: enumerable properties of prototypes are visited too.
// - Non-enumerable properties are skipped (e.g. built-in methods).
// - Symbol keys are never visited.
// - A property on the object shadows a same-named one on the prototype (visited once).
// - Order: integer-like keys ascending first, then string keys in creation order.
// - Avoid for...in on arrays: indexes are strings, and extra enumerable props appear.
// - for...of iterates values of iterables; for...in iterates keys.

js-easy-78.syntax:
// General form
// JSON.stringify(value, replacer?, space?)
// Returns a JSON string (or undefined for some top-level inputs).

// Example 1: how different property values are handled
const s1 = JSON.stringify({ n: 5, f() {}, t: true, nul: null });
// Each value type has its own rule in objects.

// Example 2: arrays vs. objects
const s2 = JSON.stringify([function () {}, Symbol('x')]);
// Array slots must keep their positions, so they are treated differently
// from object properties.

// Gotchas / variations
// - Values with no JSON representation (undefined, functions, symbols)
//   are handled differently depending on whether they appear in an
//   object property, an array element, or at the top level.
// - null is a valid JSON value and is kept.
// - NaN, Infinity and -Infinity become null.
// - Symbol-keyed properties are ignored.
// - Only own enumerable string-keyed properties are included.
// - Date uses toJSON; any object with toJSON() is serialized from its result.
// - BigInt throws a TypeError unless you provide toJSON or a replacer.
// - Circular references throw a TypeError.
// - replacer (function or array of keys) can filter or transform values.
// - space (number or string) pretty-prints the output.

js-easy-79.syntax:
// General form
// JSON.stringify(value, replacer?, space?)  -> string (or undefined)

// JSON has no representation for some JS values, so stringify
// handles them differently depending on WHERE they appear.

// 1) As object property values: the property is omitted
JSON.stringify({ a: 1, b: function () {}, c: Symbol('s') });
// -> '{"a":1}'

// 2) As array elements: the slot must stay, so a placeholder is written
JSON.stringify([function () {}, Symbol('s')]);
// -> '[null,null]'

// 3) As the top-level value: the result is the value undefined (not a string)
JSON.stringify(function () {});
// -> undefined

// Gotchas (comments only):
// - Values skipped in objects / replaced in arrays: undefined, functions, symbols.
// - NaN, Infinity, -Infinity become null everywhere.
// - Sparse array holes are visited as undefined, so follow the array rule.
// - Date uses toJSON() and becomes an ISO string.
// - BigInt throws a TypeError.
// - A replacer function or toJSON() can change what gets serialized.

js-easy-80.syntax:
// General form
// JSON.stringify(value, replacer?, space?)
// Returns a JSON string (or undefined for some top-level inputs).

// Example 1: which values survive inside an object
const o = { n: 5, s: "hi", t: true, nul: null, d: new Date(0) };
JSON.stringify(o);
// numbers, strings, booleans, null are kept; Date uses toJSON() -> ISO string

// Example 2: arrays vs objects
JSON.stringify([1, undefined, Symbol("x")]);
// In ARRAYS, unsupported values are converted to null (keeps positions)

// Example 3: replacer and indentation
JSON.stringify({ x: 1, y: 2 }, ["x"]);        // array replacer = allowed keys
JSON.stringify({ x: 1 }, null, 2);             // pretty print with 2 spaces
JSON.stringify({ x: 1, y: 2 }, (k, v) => typeof v === "number" ? v * 2 : v);

// Gotchas (comments)
// - Object properties whose values are undefined, functions, or symbols are
//   handled specially: they are not written as normal values.
// - Top-level undefined/function/symbol input returns undefined (not a string).
// - NaN and Infinity become null.
// - If an object has toJSON(), its return value is serialized instead.
// - Circular references throw TypeError; BigInt throws TypeError.
// - Only own enumerable string-keyed properties are included.
// - Map/Set serialize as {} unless converted first.

js-easy-86.syntax:
// General form
function name(param = defaultExpression) { /* ... */ }
const arrow = (param = defaultExpression) => { /* ... */ };

// Example
function greet(name = "guest", punct = "!") {
  return "Hi " + name + punct;
}

// Notes and gotchas (as comments):
// - The default expression is evaluated at call time, each call,
//   only when the default is actually needed.
// - Defaults can use earlier parameters:
//     function box(w, h = w) { return w * h; }
// - Defaults can call functions:
//     function stamp(t = Date.now()) { return t; }
// - A parameter with a default does not count toward fn.length
//   (length stops counting at the first parameter with a default).
// - Parameters with defaults may come before required ones, but
//   callers must then pass undefined explicitly to get the default.
// - Destructuring can have defaults too:
//     function cfg({ mode = "fast" } = {}) { return mode; }
// - Other falsy values (0, "", false, NaN) are ordinary values.
//   Compare with the || operator, which tests truthiness instead.
// - Think about which values count as "missing" for the parameter:
//   the rule is a strict check against one specific value.

js-easy-87.syntax:
// General form
// function name(p1, p2 = expression, p3 = expression) { ... }
//
// A default is evaluated at call time, only when the argument is
// undefined (missing or explicitly undefined). Not for null, 0, '' or false.
// Parameters are initialized left to right, each in its own scope
// step, like let bindings.

function area(w, h = w * 2) {
  return w * h;
}

function tag(name, label = name.toUpperCase(), note = label + '!') {
  return note;
}

// Variations and gotchas:
// - Defaults can call functions: function g(x = makeId()) {}
//   makeId runs on every call that needs it, not once.
// - Defaults can use outer variables and earlier parameters.
// - Temporal dead zone applies to parameters: a default that reads
//   a parameter declared later (or itself) throws a ReferenceError.
//     function bad(a = b, b = 1) {}
// - Parameters with defaults do not count toward function.length
//   after the first default.
// - Destructuring can have defaults too: function h({ x = 1 } = {}) {}
// - With defaults present, the parameter list has its own scope,
//   separate from the function body's var declarations.

js-easy-89.syntax:
// General form
switch (expression) {
  case valueA:
    // statements
    break;
  case valueB:
    // statements
    break;
  default:
    // statements when no case matches
}

// Example 1: matching uses strict equality (===)
let color = "red";
switch (color) {
  case "red":
    console.log("stop");
    break;
  case "green":
    console.log("go");
    break;
  default:
    console.log("unknown");
}

// Example 2: several labels sharing one block
let day = 6;
switch (day) {
  case 6:
  case 7:
    console.log("weekend");
    break;
  default:
    console.log("weekday");
}

// Notes and gotchas
// - Execution starts at the first matching case, then continues
//   statement by statement until a break, return, throw, or the end
//   of the switch block. Labels themselves do not stop execution.
// - An empty case with no statements simply continues into the next one.
// - default can appear anywhere; it runs only if no case matches,
//   but if it is not last, flow still continues past it without break.
// - "5" and 5 do not match (strict equality).
// - All cases share one block scope; wrap a case in { } to use let/const safely.
// - Intentional continuing into the next case is best marked with a comment.

js-easy-90.syntax:
// General form
//   void <expression>
// A unary operator (same precedence level as typeof, delete, !).
// The operand is evaluated for its side effects, and the
// operator's own result is a fixed value you can look up in the docs.

// Example 1: side effect still happens
let count = 0;
const r = void (count += 5);
console.log(count); // 5  (operand was evaluated)
// r holds whatever void always yields

// Example 2: discarding a function's return value
void console.log('hi'); // still logs

// Common uses
//   <a href="javascript:void(0)">link</a>  (legacy: do nothing on click)
//   Arrow function that must not return a value:
//     const handler = () => void doWork();
//   Immediately invoked function expression:
//     void function () { /* ... */ }();

// Gotchas
//   - Precedence: void binds tightly, so use parentheses
//     for compound expressions: void (a + b)
//     versus (void a) + b
//   - void is an operator, not a function: void(x) is just
//     void applied to a parenthesized expression.
//   - It always evaluates its operand, even if the result is ignored.

js-easy-91.syntax:
// General form
//   delete object.property
//   delete object[expression]
// The result is a boolean, not the deleted value.

const cfg = { host: "x", port: 80 };
const r1 = delete cfg.port;     // removes the property from cfg
const r2 = delete cfg.missing;  // property does not exist

// Property attributes matter:
const locked = {};
Object.defineProperty(locked, "id", { value: 7, configurable: false });
// delete locked.id -> property stays
//   sloppy mode: evaluates to false
//   strict mode ("use strict", modules, classes): throws TypeError

// Gotchas
// - Only own properties are removed; inherited ones on the prototype are untouched.
// - Deleting a nonexistent property does not fail.
// - delete on a plain variable name is a SyntaxError in strict mode.
// - Variables declared with var/let/const are not configurable properties.
// - Array elements: delete arr[i] leaves a hole and does not change length.
// - Use Reflect.deleteProperty(obj, key) to get a boolean without throwing.
// - Object.freeze / Object.seal make all own properties non-configurable.

js-easy-92.syntax:
// General form
//   delete object.property
//   delete object[expression]
// Returns true if the property is gone or never existed;
// false (or TypeError in strict mode) if it is non-configurable.

// Example with an object
const user = { name: "Ana", age: 30 };
delete user.age;
console.log("age" in user); // false

// Example with an array (different values from any quiz code)
const nums = [10, 20, 30, 40];
delete nums[2];
// Compare these afterwards:
//   nums.length   -> read it and think about what delete touches
//   2 in nums     -> checks whether the index property exists
//   nums[2]       -> reading a missing property gives undefined

// Gotchas
// - delete removes a property; it does not shift other elements
//   and does not renumber indexes.
// - Arrays can become sparse (have empty slots).
// - forEach, map, and for...in skip empty slots;
//   a for loop with an index and for...of do not skip them
//   (for...of yields undefined for them).
// - To remove and re-pack elements, use splice(start, count).
// - To set a value but keep the slot, assign undefined.
// - delete on a plain variable does nothing useful.

js-easy-93.syntax:
// General form
//   propertyKey in object
// Left side: string or symbol (numbers are converted to strings)
// Right side: must be an object, otherwise TypeError
// Returns a boolean

const base = { kind: "base" };
const child = Object.create(base);   // child's prototype is base
child.own = 1;

"own" in child;      // checks child itself
"kind" in child;     // also consults the prototype chain
"missing" in child;  // not found anywhere on the chain

// Arrays: the key is an index (as a string) or property name
2 in [10, 20, 30];       // index 2 exists
"length" in [];          // array own property

// Gotchas
// - `in` walks the whole prototype chain.
// - Use Object.hasOwn(obj, key) to test only own properties.
// - A property set to undefined still counts as present.
// - Non-enumerable properties are still found by `in`.
// - "x" in "text" throws TypeError (primitive on the right).
// - Private fields: #priv in obj is a separate brand check form.
// - Objects with a null prototype (Object.create(null)) inherit nothing.

js-easy-95.syntax:
// General form: methods that list an object's own keys
// Object.keys(o)                    -> own enumerable string keys
// Object.getOwnPropertyNames(o)     -> own string keys, enumerable or not
// Object.getOwnPropertySymbols(o)   -> own symbol keys
// Reflect.ownKeys(o)                -> all own keys (strings + symbols)

const box = {};
Object.defineProperty(box, "secret", { value: 10, enumerable: false });
const tag = Symbol("tag");
box[tag] = 20;
box.name = "x";

console.log(Object.getOwnPropertyNames(box)); // includes non-enumerable strings
console.log(Object.getOwnPropertySymbols(box)); // symbol keys only
console.log(Reflect.ownKeys(box)); // everything own

// Variations and gotchas:
// - defineProperty defaults: enumerable, writable, configurable are all false
// - Plain assignment (o.a = 1) creates an enumerable property
// - Object.values / Object.entries / for...in / JSON.stringify also
//   consider only enumerable string-keyed properties
// - for...in also walks inherited enumerable properties; Object.keys does not
// - Object.assign and spread {...o} copy own enumerable props,
//   including enumerable symbols
// - o.propertyIsEnumerable(key) tests a single own key

js-easy-96.syntax:
// General form
// Math.max(...values)  -> largest of the numeric arguments
// Math.min(...values)  -> smallest of the numeric arguments
// Arguments are converted to numbers before comparing.

// Examples
Math.max(3, 9, 4);        // 9
Math.min(3, 9, 4);        // 3
Math.max(...[5, 12, 7]);  // 12 (spread an array into arguments)

// Variations and gotchas
// - Math.max/min do not accept an array directly: Math.max([1, 2]) converts the
//   array to a number (NaN for multi-element arrays).
// - If any argument converts to NaN, the result is NaN.
// - Non-numbers are coerced: Math.max('8', 2) uses 8; null becomes 0; undefined becomes NaN.
// - Think of each function as folding over its arguments, starting from an
//   identity value that any real number would beat. Consider what that
//   starting value must be for each function when nothing is passed.
// - Very large arrays spread as arguments can exceed engine argument limits;
//   use reduce for huge inputs:
//   arr.reduce((a, b) => Math.max(a, b), -Infinity)
// - Math.max(-0, 0) is 0 (+0 is treated as larger than -0).

js-easy-98.syntax:
// General form
//   left + right
// Evaluation (simplified):
//   1. Convert both operands to primitives (objects -> valueOf/toString).
//   2. If EITHER primitive is a string, convert the other to a string
//      and concatenate.
//   3. Otherwise convert both to numbers and add.

// Examples with different values
let a = 'age: ' + 30;      // string side wins -> concatenation
let b = 2 + 3;             // both numbers -> numeric addition
let c = true + 1;          // no string: boolean becomes a number

// Gotchas
// - Evaluation is left to right, so grouping matters:
//     1 + 2 + 'x'   // numbers added first, then joined with string
//     'x' + 1 + 2   // string joined at each step
// - Other arithmetic operators (-, *, /) always convert to numbers;
//   only + has the string-concatenation behavior.
// - Unary + converts to a number: +'7'
// - Template literals avoid ambiguity: `${x}${y}`
// - null -> 0, undefined -> NaN, arrays -> their toString() text
//   when used with +.

js-easy-100.syntax:
// General form
//   left + right
// 1. Both operands are converted to primitives.
// 2. If either primitive is a string -> string concatenation.
// 3. Otherwise both are converted to numbers (or BigInt) -> addition.

// Examples
null + 5;        // number conversion path
"a" + 1;         // string path

// ToNumber conversions for non-string primitives:
//   undefined -> NaN
//   null      -> 0
//   false     -> 0
//   true      -> 1 (see the rule above)

// Variations and gotchas
// - Mixing BigInt and Number throws a TypeError.
// - Objects use valueOf()/toString() (or Symbol.toPrimitive) first;
//   Date objects prefer string.
// - Unary + forces number conversion: +"42" -> 42
// - Other arithmetic operators (-, *, /) always convert to numbers,
//   so only + has the string-concatenation behavior.
// - Evaluation is left to right: 1 + 2 + "3" differs from "1" + 2 + 3.
// - Use Number(x) or template literals to make intent explicit.
